'use strict';
const ms={datasets:[],active:null,counter:0,scan:0,peak:null,ions:[31,45,46],normalize:false,massRange:'auto',average:.4,subtract:true,bgStart:0,bgEnd:.1,hits:[],candidate:null,searchKey:null,message:'Select the MS detector, prepare the instrument and inject a sample, or load the alcohol tutorial.'};
const MS_MIN=10,MS_MAX=200,MS_DT=.2/60,msCache=new Map(),msRefs=new Map(MS_LIBRARY.map(r=>{const peaks=r.peaks.filter(([mz])=>mz>=MS_MIN&&mz<=MS_MAX),sum=peaks.reduce((n,p)=>n+p[1],0);return [r.id,{...r,weights:peaks.map(([mz,v])=>[mz,v/sum])}]}));
try{const s=JSON.parse(localStorage.getItem('simlab-ms-analysis')||'null');if(s&&Array.isArray(s.datasets)){ms.datasets=s.datasets.filter(d=>d.kind==='SIMLAB_MS_COMPANION'&&d.acquired>0&&d.acquired<=120&&Array.isArray(d.components)&&d.components.every(c=>msRefs.has(c.id))).slice(-4).map(d=>({...d,live:false,complete:d.live?false:d.complete,interrupted:!!d.live}));ms.active=ms.datasets.some(d=>d.id===s.active)?s.active:ms.datasets.at(-1)?.id||null;ms.counter=Number(s.counter)||0;}}catch{}
function msData(){return ms.datasets.find(d=>d.id===ms.active)||null}
function msSave(){try{localStorage.setItem('simlab-ms-analysis',JSON.stringify({datasets:ms.datasets,active:ms.active,counter:ms.counter}));return true}catch{ms.message='Browser storage is full or unavailable. This analysis remains in this session; export a report before leaving.';return false}}
function msRender(){msSave();if(typeof page!=='undefined'&&page==='massspec')render()}
function msEsc(x){return gcPrepEsc(x)}
function msCanTransfer(){return !!gc.run&&gcIsMS(gc.run.method)&&(gc.run.completed||gc.run.stopped)&&!gc.running&&!gc.paused&&!gseq.active&&gc.time>0}
function msSampleTrace(times,signal,acquired){const end=Math.min(times.length-1,Math.floor(acquired/(times[1]-times[0]))),stride=Math.max(1,Math.ceil((end+1)/1800)),out=[];for(let i=0;i<=end;i+=stride){let lo=i,hi=i;for(let j=i+1;j<=Math.min(end,i+stride-1);j++){if(signal[j]<signal[lo])lo=j;if(signal[j]>signal[hi])hi=j}for(const j of [...new Set([lo,hi])].sort((a,b)=>a-b))out.push([times[j],signal[j]])}return out}
function msMakeDataset(run,acquired,title,source='GC-FID transfer'){if(!Number.isFinite(acquired)||acquired<=0||acquired>run.duration+1e-8)throw Error('No valid acquired GC time range.');if(run.components.some(c=>!msRefs.has(c.id)))throw Error('This sample contains a compound without a reference EI spectrum.');return {kind:'SIMLAB_MS_COMPANION',schema:1,acquisition:gcIsMS(run.method)?'direct':'legacy-companion',id:'ms-'+Date.now().toString(36)+'-'+(++ms.counter),title:String(title).slice(0,120),created:new Date().toISOString(),source,acquired,complete:!!run.completed,dt:MS_DT,method:{...run.method},components:run.components.map(c=>({id:c.id,name:c.name,mass:c.mass,tr:c.tr,sigma:c.sigma})),fid:gcIsMS(run.method)?[]:msSampleTrace(run.times,run.signal,acquired),sourcePeaks:run.peaks.filter(p=>p.right<=acquired+1e-8).map(p=>({number:p.number,tr:p.tr,area:p.area,height:p.height})),assignments:[],notes:''}}
function msAddDataset(d){ms.datasets.push(d);ms.datasets=ms.datasets.slice(-4);for(const k of msCache.keys())if(!ms.datasets.some(d=>d.id===k))msCache.delete(k);msSelectDataset(d.id);msSave()}
function msTransferGC(){if(!msCanTransfer()){gcMessage('Complete or stop acquisition before exporting the acquired chromatogram to MS.');gcRender();return false}try{if(gc.run.msDatasetId&&ms.datasets.some(d=>d.id===gc.run.msDatasetId))msSelectDataset(gc.run.msDatasetId);else{const label=gc.run.calibration?gcVialLabel(gc.run.calibration):'GC-FID run '+(ms.counter+1),d=msMakeDataset(gc.run,gc.time,label);gc.run.msDatasetId=d.id;msAddDataset(d);}ms.message='Direct MS acquisition opened.';go('massspec');return true}catch(e){gcMessage(e.message);gcRender();return false}}
function msBackground(mz,t){let v=.1+.025*(1+Math.sin(mz*1.73+t*23.7))+.008*(1+Math.sin(mz*.71+t*117));if(mz===18)v+=4;if(mz===28)v+=2;if(mz===32)v+=1;if(mz===73)v+=1.5+.01*t;if(mz===147)v+=.6;return v}
function msAmplitude(c,t){if(c.tr===null||!Number.isFinite(c.sigma)||c.sigma<=0)return 0;const z=(t-c.tr)/c.sigma;if(Math.abs(z)>7)return 0;const ref=msRefs.get(c.id),area=c.mass*1500*(.7+ref.mw/200);return area/(c.sigma*60*Math.sqrt(2*Math.PI))*Math.exp(-.5*z*z)}
function msRawAt(d,index){index=Math.max(0,Math.min(Math.floor(d.acquired/d.dt),Math.round(index)));const t=index*d.dt,a=new Float64Array(MS_MAX+1);for(let m=MS_MIN;m<=MS_MAX;m++)a[m]=msBackground(m,t);for(const c of d.components){const amp=msAmplitude(c,t);if(amp)for(const[m,v]of msRefs.get(c.id).weights)a[m]+=amp*v}return a}
function msIonAt(d,t,mz){let y=msBackground(mz,t);for(const c of d.components){const amp=msAmplitude(c,t);if(amp)y+=amp*(msRefs.get(c.id).weights.find(p=>p[0]===mz)?.[1]||0)}return y}
function msTrace(d){if(msCache.has(d.id))return msCache.get(d.id);const n=Math.floor(d.acquired/d.dt)+1,times=Float64Array.from({length:n},(_,i)=>i*d.dt),tic=new Float64Array(n),baseline=new Float64Array(n);for(let i=0;i<n;i++){let b=0;for(let m=MS_MIN;m<=MS_MAX;m++)b+=msBackground(m,times[i]);baseline[i]=b;tic[i]=b+d.components.reduce((s,c)=>s+msAmplitude(c,times[i]),0)}const top=Math.max(1,...Array.from(tic,(v,i)=>v-baseline[i])),scaled=Float64Array.from(tic,(v,i)=>(v-baseline[i])/top*100+gcBaseline(times[i]));const peaks=gcIntegratePeaks(times,scaled,[],d.dt,true).filter(p=>p.height>=.5).map((p,i)=>({...p,number:i+1,height:p.height*top/100,area:p.area*top/100})),data={times,tic,baseline,peaks,eic:new Map()};msCache.set(d.id,data);return data}
function msEIC(d,ion){const c=msTrace(d);if(!c.eic.has(ion))c.eic.set(ion,Float64Array.from(c.times,t=>msIonAt(d,t,ion)));return c.eic.get(ion)}
function msInvalidate(){ms.hits=[];ms.candidate=null;ms.searchKey=null}
function msSelectDataset(id){ms.active=id;ms.peak=null;ms.scan=0;msInvalidate();const d=msData();if(!d)return;const p=msTrace(d).peaks[0];if(p)msSelectPeak(p.number);else{ms.bgStart=0;ms.bgEnd=Math.min(d.acquired,.1)}}
function msSelectPeak(number){const d=msData(),p=d&&msTrace(d).peaks.find(p=>p.number===number);if(!p)return;ms.peak=number;ms.scan=Math.min(Math.floor(d.acquired/d.dt),Math.round(p.tr/d.dt));ms.bgStart=Math.max(0,p.left-.25);ms.bgEnd=Math.max(0,p.left-.05);if(ms.bgEnd<=ms.bgStart)ms.bgEnd=Math.min(d.acquired,ms.bgStart+d.dt);msInvalidate()}
function msSetScan(index){const d=msData();if(!d)return;ms.scan=Math.max(0,Math.min(Math.floor(d.acquired/d.dt),Math.round(index)));ms.peak=msTrace(d).peaks.find(p=>ms.scan*d.dt>=p.left&&ms.scan*d.dt<=p.right)?.number||null;msInvalidate()}
function msKey(){return JSON.stringify([ms.active,ms.scan,ms.average,ms.subtract,ms.bgStart,ms.bgEnd])}
function msSpectrum(d=msData()){if(!d)throw Error('Load a dataset first.');if(!Number.isFinite(ms.average)||ms.average<0||ms.average>10)throw Error('Use a spectrum averaging width from 0 to 10 seconds.');const last=Math.floor(d.acquired/d.dt),center=Math.max(0,Math.min(last,Math.round(ms.scan))),half=Math.round(ms.average/120/d.dt),lo=Math.max(0,center-half),hi=Math.min(last,center+half),out=new Float64Array(MS_MAX+1);for(let i=lo;i<=hi;i++){const a=msRawAt(d,i);for(let m=MS_MIN;m<=MS_MAX;m++)out[m]+=a[m]/(hi-lo+1)}if(ms.subtract){if(!Number.isFinite(ms.bgStart)||!Number.isFinite(ms.bgEnd)||ms.bgStart<0||ms.bgEnd<=ms.bgStart||ms.bgEnd>d.acquired+1e-8)throw Error('Set a background window inside the acquired run, with end greater than start.');const b0=Math.ceil(ms.bgStart/d.dt),b1=Math.min(last,Math.floor(ms.bgEnd/d.dt));if(b1<b0)throw Error('The background window must contain at least one acquired scan.');const bg=new Float64Array(MS_MAX+1);for(let i=b0;i<=b1;i++){const a=msRawAt(d,i);for(let m=MS_MIN;m<=MS_MAX;m++)bg[m]+=a[m]/(b1-b0+1)}for(let m=MS_MIN;m<=MS_MAX;m++)out[m]=Math.max(0,out[m]-bg[m]);}return out}
function msCosine(a,peaks){let dot=0,aa=0,bb=0;for(let m=MS_MIN;m<=MS_MAX;m++)aa+=a[m]*a[m];for(const[m,v]of peaks)if(m>=MS_MIN&&m<=MS_MAX){dot+=a[m]*v;bb+=v*v}return aa>0&&bb>0?100*dot/Math.sqrt(aa*bb):0}
function msSearch(){const a=msSpectrum(),max=Math.max(...a);if(max<1)throw Error('Too little background-corrected signal. Select a chromatographic peak.');ms.hits=MS_LIBRARY.map(r=>({id:r.id,score:msCosine(a,r.peaks)})).sort((a,b)=>b.score-a.score).slice(0,5);ms.candidate=ms.hits[0]?.id||null;ms.searchKey=msKey();ms.message='Library search complete. Scores are cosine similarities to 15 reference EI patterns, not identification probabilities or vendor match factors.'}
function msAssign(){const d=msData(),p=d&&msTrace(d).peaks.find(p=>p.number===ms.peak);if(!p||ms.scan*d.dt<p.left||ms.scan*d.dt>p.right)throw Error('Select a detected TIC peak before assigning an identity.');if(ms.searchKey!==msKey()||!ms.candidate)throw Error('Search the current spectrum first.');const hit=ms.hits.find(h=>h.id===ms.candidate);d.assignments=d.assignments.filter(a=>a.peak!==p.number);d.assignments.push({peak:p.number,candidate:hit.id,score:hit.score,tr:p.tr,area:p.area,height:p.height,scanTime:ms.scan*d.dt,average:ms.average,background:ms.subtract?[ms.bgStart,ms.bgEnd]:null,quality:p.partial?'Truncated peak':p.overlap?'Possible overlap':'Tentative',created:new Date().toISOString()});ms.message='Tentative identity recorded. Confirm with an authentic standard and supporting ions; co-elution and similar spectra can mislead.';msSave()}
function msParseIons(text){const parts=String(text).split(/[ ,;]+/).filter(Boolean),ions=parts.map(Number);if(!ions.length||ions.length>6||ions.some(m=>!Number.isInteger(m)||m<MS_MIN||m>MS_MAX))throw Error('Enter one to six integer ions from m/z 10 to 200.');return [...new Set(ions)]}
function msPolyline(times,values,X,Y,maxPoints=1200){const stride=Math.max(1,Math.ceil(times.length/(maxPoints/2))),points=[];for(let i=0;i<times.length;i+=stride){let lo=i,hi=i;for(let j=i+1;j<Math.min(times.length,i+stride);j++){if(values[j]<values[lo])lo=j;if(values[j]>values[hi])hi=j}for(const j of [...new Set([lo,hi])].sort((a,b)=>a-b))points.push(X(times[j]).toFixed(2)+','+Y(values[j]).toFixed(2))}return points.join(' ')}
function msChromatogram(d){const duration=Math.max(d.dt,d.acquired),c=msTrace(d),colors=['#bd7541','#8d65b4','#337eae','#b05066','#849548','#489989'],traces=[{name:'TIC',color:'#087e67',values:c.tic},...ms.ions.map((ion,i)=>({name:'EIC '+ion,color:colors[i],values:msEIC(d,ion)}))],max=Math.max(1,...traces.map(t=>Math.max(...t.values))),X=t=>65+875*t/duration,Y=y=>225-185*y/(ms.normalize?100:max*1.08);return `<svg data-ms-chrom viewBox="0 0 960 280" role="img" aria-label="Simulated MS total and extracted ion chromatograms; click to select a scan"><rect width="960" height="280" fill="#fbfdfb"/>${[0,1,2,3,4].map(i=>`<path d="M65 ${225-46.25*i}H940" stroke="#e0e9e3"/><text x="56" y="${229-46.25*i}" text-anchor="end">${gcFmt((ms.normalize?100:max*1.08)*i/4,ms.normalize?0:1)}</text><text x="${65+218.75*i}" y="245" text-anchor="middle">${gcFmt(d.acquired*i/4,2)}</text>`).join('')}${traces.map(t=>{const scale=ms.normalize?100/Math.max(1e-9,...t.values):1;return `<polyline points="${msPolyline(c.times,t.values,X,v=>Y(v*scale))}" fill="none" stroke="${t.color}" stroke-width="${t.name==='TIC'?1.8:1.25}"/>`}).join('')}<path d="M${X(Math.min(d.acquired,ms.scan*d.dt))} 35V225" stroke="#bd7541" stroke-dasharray="4 3"/>${c.peaks.map(p=>`<text x="${X(p.tr)}" y="${Math.max(25,Y(ms.normalize?100:p.height)+2)}" text-anchor="middle">${p.number}</text>`).join('')}<text x="500" y="269" text-anchor="middle">Retention time / min</text><text x="17" y="135" text-anchor="middle" transform="rotate(-90 17 135)">${ms.normalize?'Each trace normalized / %':'Simulated ion signal / a.u.'}</text></svg><div class="ms-legend">${traces.map(t=>`<span><i style="background:${t.color}"></i>${t.name}</span>`).join('')}</div>`}
function msSpectrumPlot(a){const r=msRefs.get(ms.candidate),max=Math.max(1,...a),displayMax=ms.massRange==='full'?MS_MAX:Math.min(MS_MAX,Math.max(60,Math.ceil((Math.max(r?.nominalMass||0,...Array.from(a,(v,m)=>v/max>.005?m:0))+5)/10)*10)),X=m=>50+870*(m-MS_MIN)/(displayMax-MS_MIN),Y=v=>142-v*1.05;return `<svg viewBox="0 0 960 310" role="img" aria-label="Observed mass spectrum above baseline and selected reference spectrum mirrored below"><rect width="960" height="310" fill="#fbfdfb"/><path d="M50 142H930" stroke="#95aa9d"/>${Array.from({length:MS_MAX-MS_MIN+1},(_,i)=>i+MS_MIN).filter(m=>m<=displayMax&&a[m]/max>.002).map(m=>`<path data-ms-ion="${m}" d="M${X(m)} 142V${Y(a[m]/max*100)}" stroke="#087e67" stroke-width="2"><title>m/z ${m}: ${gcFmt(a[m],2)} a.u.; ${gcFmt(a[m]/max*100,1)}%</title></path>`).join('')}${r?r.peaks.filter(([m,v])=>m>=MS_MIN&&m<=displayMax&&v>.2).map(([m,v])=>`<path d="M${X(m)} 142V${142+v*1.05}" stroke="#bd7541" stroke-width="1.6"/>`).join(''):''}${Array.from({length:Math.floor(displayMax/20)},(_,i)=>20+i*20).map(m=>`<text x="${X(m)}" y="280" text-anchor="middle">${m}</text>`).join('')}${Array.from(a,(v,m)=>({v,m})).sort((x,y)=>y.v-x.v).reduce((out,p)=>out.length<6&&out.every(q=>Math.abs(q.m-p.m)>=5)?[...out,p]:out,[]).map(({m,v})=>v/max>.02?`<text x="${X(m)}" y="${Y(v/max*100)-7}" text-anchor="middle">${m}</text>`:'').join('')}<text x="60" y="20">Observed · relative intensity</text><text x="60" y="263">${r?'Reference: '+msEsc(r.name):'Run a library search to add a reference spectrum'}</text><text x="500" y="302" text-anchor="middle">m/z · nominal mass (unit resolution)</text></svg>`}
function msPeakTable(d){const c=msTrace(d);return `<div class="gc-table-wrap"><table class="gc-table"><thead><tr><th>Peak</th><th>TIC tR / min</th><th>Height / a.u.</th><th>Area / a.u.·s</th><th>Resolution</th><th>Tentative assignment</th></tr></thead><tbody>${c.peaks.map(p=>{const a=d.assignments.find(a=>a.peak===p.number);return `<tr data-ms-peak="${p.number}" class="${ms.peak===p.number?'ms-selected':''}"><td>${p.number}</td><td>${gcFmt(p.tr,4)}</td><td>${gcFmt(p.height,2)}</td><td>${gcFmt(p.area,2)}</td><td>${p.resolution===null?'—':gcFmt(p.resolution,2)}${p.partial?' · cut off':p.overlap?' · overlap':''}</td><td>${a?msEsc(msRefs.get(a.candidate)?.name||a.candidate)+' · '+gcFmt(a.score,1):'Unassigned'}</td></tr>`}).join('')||'<tr><td colspan="6">No detectable MS peaks in the acquired interval.</td></tr>'}</tbody></table></div>`}
function msLibraryPanel(a){const hits=ms.searchKey===msKey()?ms.hits:[],r=msRefs.get(ms.candidate),base=Array.from(a).reduce((best,v,m)=>v>a[best]?m:best,MS_MIN);return `<div class="ms-title"><h2>Library comparison</h2><button class="btn small" data-ms-action="search">Search spectrum</button></div><p>Base peak: <b>m/z ${base}</b>. Similarity is 100 × cosine of the full nominal-mass vectors. It is not a probability or an Agilent/NIST match factor.</p><div class="gc-table-wrap"><table class="gc-table"><thead><tr><th>Candidate</th><th>Formula</th><th>Similarity / 100</th></tr></thead><tbody>${hits.map(h=>{const ref=msRefs.get(h.id);return `<tr data-ms-hit="${h.id}" class="${ms.candidate===h.id?'ms-selected':''}"><td>${ref.name}</td><td>${ref.formula}</td><td>${gcFmt(h.score,2)}</td></tr>`}).join('')||'<tr><td colspan="3">Select a peak, check its spectrum and search the library.</td></tr>'}</tbody></table></div>${hits.length&&hits[0].score-hits[1].score<5?'<p class="gc-notice gc-warn">The leading candidates have similar scores. Compare molecular ions, diagnostic fragments and retention against standards.</p>':''}${r&&hits.length?`<p><b>${r.name}</b> · average molecular mass ${r.mw} g/mol · reference molecular-ion region near nominal m/z ${r.nominalMass}. Molecular ions can be weak or absent.</p><p><a href="${r.source}" target="_blank" rel="noopener">NIST EI reference · record ${msEsc(r.record)}</a>. ${msEsc(r.origin)}</p><button class="btn" data-ms-action="assign" ${!ms.peak?'disabled':''}>Assign tentative identity</button>`:''}<p>Shared fragments and co-elution can yield misleading matches. This 15-compound teaching library cannot rule out compounds outside it. No spectral deconvolution or definitive identification is claimed.</p>`}
function msAnalysis(){const d=msData();return `${head('INSTRUMENTATION · QUALITATIVE ANALYSIS','MS data analysis','Follow a chromatographic peak into its ions, compare EI spectra and build a tentative identification report.')}<div class="ms-toolbar"><span class="pill">SIMULATED GC–MS · EI</span><button class="btn secondary" data-ms-action="demo" ${typeof gcIsMS==='function'&&gcIsMS()&&(gcLocked()||gseq.active)?'disabled':''}>Load alcohol tutorial</button><button class="btn secondary" data-go="instrumentation">GC instrument setup</button></div>${typeof gcMSPanel==='function'?gcMSPanel():''}<div class="gc-notice ms-boundary"><b>Select the detector before acquisition.</b> MS mode acquires synthetic nominal-mass EI spectra directly from the simulated GC bands, with NIST reference fragmentation patterns. FID is a separate detector choice. Vacuum, temperatures and signals are teaching simulations; this station is independently built and is not Agilent MassHunter or a vendor .D file reader.</div><div class="gc-notice" role="status">${msEsc(ms.message)}</div><div class="ms-workspace"><aside class="panel gc-panel ms-files"><span class="eyebrow">DATA EXPLORER</span><h2>MS runs</h2><p>The four most recent MS datasets are stored on this browser when space permits.</p>${ms.datasets.map(x=>`<button class="ms-file ${x.id===ms.active?'active':''}" data-ms-dataset="${x.id}"><b>▤ ${msEsc(x.title)}</b><small>${gcFmt(x.acquired,2)} min · ${x.complete?'Complete':'Stopped / acquired portion'}</small></button>`).join('')||'<p>No MS run loaded. Select MS, prepare its vacuum and temperatures, then inject a sample.</p>'}${d?`<hr><span class="eyebrow">ACQUISITION SNAPSHOT</span><p>${msEsc(d.source)}<br>${GC_COLUMNS[d.method.column]?.name||'Column'}<br>${d.method.ovenMode==='program'?d.method.initial+' → '+d.method.final+' °C':d.method.initial+' °C isothermal'}<br>Source injection ${d.method.volume} µL<br>MS scan interval 0.2 s<br>m/z 10–200, nominal mass</p><p>${d.instrument?`Recorded MS conditions: source ${gcFmt(d.instrument.sourceC,0)} °C; quad ${gcFmt(d.instrument.quadC,0)} °C; transfer ${gcFmt(d.instrument.transferC,0)} °C; vacuum ${d.instrument.pressureTorr.toExponential(2)} Torr.<br>`:''}MS intensities and response factors are synthetic and independent of FID area. Concentration cannot be inferred from MS area without an MS calibration.</p>`:''}</aside><div class="ms-main">${d?`<fieldset class="ms-analysis-lock" ${d.live?'disabled':''}>${msDatasetView(d)}</fieldset>`:'<section class="panel gc-panel ms-empty"><h2>Start with a chromatogram</h2><p>1. Select MS as the acquisition detector.<br>2. Load a prepared sample, power on, enable carrier gas and select Prepare MS.<br>3. Inject &amp; run MS; watch the live TIC and instrument readouts.<br>4. After acquisition, select a TIC peak, inspect its ions and record tentative identifications.</p><p>The alcohol tutorial provides an immediate practice dataset without changing your GC instrument.</p></section>'}</div></div>`}
function msDatasetView(d){let spectrum,error;try{spectrum=msSpectrum(d)}catch(e){error=e.message;spectrum=new Float64Array(MS_MAX+1)}const c=msTrace(d),maxScan=c.times.length-1;return `<section class="panel gc-panel"><div class="ms-title"><div><span class="eyebrow">CHROMATOGRAM WINDOW</span><h2>${msEsc(d.title)}</h2></div><span class="pill">TIC + EXTRACTED IONS</span></div><div class="ms-controls"><label class="gc-field">Extracted ions / m/z<input id="msIonInput" value="${ms.ions.join(', ')}" placeholder="31, 45, 46"></label><button class="btn secondary small" data-ms-action="ions">Apply ions</button><label class="gc-check"><input data-ms-field="normalize" type="checkbox" ${ms.normalize?'checked':''}>Normalize each trace</label></div><div class="gc-chart ms-chart">${msChromatogram(d)}</div><p>Click the chromatogram or a detected peak row to select a scan. TIC = total ion signal; EIC = signal at one nominal m/z. Areas are baseline-corrected TIC integrations in synthetic a.u.·s.</p>${msPeakTable(d)}${d.acquisition==='direct'?'':`<details class="gc-detail"><summary>Source GC-FID trace</summary><p>The original acquired FID signal is retained separately in pA; TIC and FID are different detector signals.</p><div class="ms-source-fid">${msFIDPlot(d)}</div></details>`}</section><section class="panel gc-panel"><div class="ms-title"><div><span class="eyebrow">MASS SPECTRUM WINDOW</span><h2>Scan at ${gcFmt(ms.scan*d.dt,4)} min</h2></div><span class="pill">${ms.subtract?'BACKGROUND SUBTRACTED':'RAW SPECTRUM'}</span></div><label class="gc-field">Spectrum display range<select data-ms-field="massRange"><option value="auto" ${ms.massRange==='auto'?'selected':''}>Auto zoom to observed ions</option><option value="full" ${ms.massRange==='full'?'selected':''}>Full acquired range · m/z 10–200</option></select></label><div class="ms-controls"><button class="btn secondary small" data-ms-action="previous">← Scan</button><input aria-label="Selected MS scan" data-ms-field="scan" type="range" min="0" max="${maxScan}" step="1" value="${ms.scan}"><button class="btn secondary small" data-ms-action="next">Scan →</button></div><div class="ms-spectrum-settings"><label class="gc-field">Average spectrum width / s<input data-ms-number="average" type="number" min="0" max="10" step=".2" value="${ms.average}"></label><label class="gc-check"><input data-ms-field="subtract" type="checkbox" ${ms.subtract?'checked':''}>Subtract background</label><label class="gc-field">Background start / min<input data-ms-number="bgStart" type="number" min="0" max="${d.acquired}" step="any" value="${gcFmt(ms.bgStart,4)}"></label><label class="gc-field">Background end / min<input data-ms-number="bgEnd" type="number" min="0" max="${d.acquired}" step="any" value="${gcFmt(ms.bgEnd,4)}"></label><button class="btn secondary small" data-ms-action="settings">Apply spectrum settings</button></div>${error?`<p class="gc-notice gc-warn">${msEsc(error)}</p>`:''}<div class="gc-chart ms-spectrum">${msSpectrumPlot(spectrum)}</div><p>The selected scan or averaged window is shown above the axis; a selected library reference is mirrored below. Intensities are normalized independently to a base peak of 100%. Click an observed ion stick to add its EIC. Background is averaged over the entered time interval, subtracted ion by ion, with negative values clipped to zero. Verify the background window is free of analyte signal.</p><details class="gc-detail"><summary>Observed ion table</summary><div class="gc-table-wrap"><table class="gc-table"><thead><tr><th>m/z</th><th>Signal / a.u.</th><th>Relative / %</th></tr></thead><tbody>${Array.from(spectrum,(v,m)=>({v,m})).filter(x=>x.m>=MS_MIN&&x.v>.005*Math.max(1,...spectrum)).sort((a,b)=>b.v-a.v).slice(0,30).map(x=>`<tr data-ms-ion="${x.m}"><td>${x.m}</td><td>${gcFmt(x.v,3)}</td><td>${gcFmt(x.v/Math.max(1,...spectrum)*100,2)}</td></tr>`).join('')}</tbody></table></div></details></section><section class="panel gc-panel">${msLibraryPanel(spectrum)}</section><section class="panel gc-panel"><div class="ms-title"><h2>Analysis report</h2><div class="gc-actions"><button class="btn secondary small" data-ms-action="export-report">Export report CSV</button><button class="btn secondary small" data-ms-action="export-spectrum">Export spectrum CSV</button><button class="btn secondary small" data-ms-action="export-traces">Export TIC / EIC CSV</button></div></div><p>${d.assignments.length} tentative assignment(s). Each report records the spectrum extraction and background settings used for that assignment.</p><label class="gc-field">Analyst notes<textarea id="msNotes" rows="3" maxlength="2000" placeholder="Record diagnostic ions and evidence for your assignments…">${msEsc(d.notes)}</textarea></label><details class="gc-detail"><summary>Teaching answer key · known simulated components</summary><p>This key is the simulation setup. Library matching above is calculated from the spectrum and does not use these labels.</p>${d.components.map(x=>`${msEsc(x.name)} · model band centre ${x.tr!==null&&x.tr<=d.acquired?gcFmt(x.tr,4)+' min':'outside acquired range'}`).join('<br>')}</details><details class="gc-detail"><summary>References and simulation limits</summary><p>Reference peak patterns come from the <a href="https://webbook.nist.gov/chemistry/" target="_blank" rel="noopener">NIST Chemistry WebBook</a>. Individual reference links and record IDs appear with candidates. <a href="ms-reference-notice.txt" target="_blank" rel="noopener">Reference attribution and data notice</a>.</p><p>This teaching workstation follows common qualitative-analysis operations such as TIC/EIC inspection, spectrum extraction and library comparison, described by <a href="https://www.agilent.com/en/product/software-informatics/mass-spectrometry-software/data-analysis/qualitative-analysis" target="_blank" rel="noopener">Agilent qualitative-analysis documentation</a>. It is independently built and not affiliated with Agilent or NIST.</p><p>EI fragmentation patterns are reference data; time-dependent MS intensities, backgrounds, response, noise and detector resolution are simplified simulations. No exact mass, isotope fitting, collision-induced MS/MS, spectral deconvolution or vendor-specific match factor is implemented. Co-eluting spectra are sums of component ion signals. The bulk sample diluent peak is omitted, as in the GC-FID workbench. Use authentic standards and a validated method for real identification.</p></details></section>`}
function msFIDPlot(d){if(!d.fid.length)return '<p>No FID signal acquired.</p>';const times=d.fid.map(x=>x[0]),values=d.fid.map(x=>x[1]),max=Math.max(1,...values);return `<svg viewBox="0 0 960 180" role="img" aria-label="Source acquired GC-FID signal in pA"><polyline points="${msPolyline(times,values,t=>55+t/d.acquired*880,v=>145-v/max*120)}" fill="none" stroke="#758b80" stroke-width="1.5"/><text x="55" y="20">Source FID / pA</text><text x="55" y="170">0 min</text><text x="850" y="170">${gcFmt(d.acquired,2)} min</text></svg>`}
function msExport(kind){const d=msData();if(!d)return;if(kind==='report'){gcDownload('SIMLAB-MS-tentative-report.csv',[['SIMULATED MS DATA','Acquisition',d.acquisition||'legacy-companion','Tentative identities only'],['dataset',d.title,'source',d.source,'acquired_min',d.acquired],['analyst_notes',d.notes],['recorded_MS_pressure_Torr',d.instrument?.pressureTorr??'','source_C',d.instrument?.sourceC??'','quad_C',d.instrument?.quadC??'','transfer_line_C',d.instrument?.transferC??''],['peak','TIC_retention_min','TIC_height_au','TIC_area_au_s','tentative_identity','cosine_similarity_0_100','spectrum_time_min','averaging_width_s','background_start_min','background_end_min','quality'],...msTrace(d).peaks.map(p=>{const a=d.assignments.find(x=>x.peak===p.number);return [p.number,p.tr,p.height,p.area,a?msRefs.get(a.candidate).name:'Unassigned',a?.score??'',a?.scanTime??'',a?.average??'',a?.background?.[0]??'',a?.background?.[1]??'',a?.quality||(p.partial?'Truncated':p.overlap?'Possible overlap':'Unassigned')]})]);}else if(kind==='spectrum'){const a=msSpectrum(d),ref=msRefs.get(ms.candidate),max=Math.max(1,...a);gcDownload('SIMLAB-MS-spectrum.csv',[['SIMULATED nominal-mass spectrum','dataset',d.title,'scan_time_min',ms.scan*d.dt],['averaging_s',ms.average,'background_subtracted',ms.subtract,'background_window_min',ms.bgStart,ms.bgEnd],['mz','signal_au','relative_percent','selected_reference_relative_percent'],...Array.from({length:MS_MAX-MS_MIN+1},(_,i)=>{const m=MS_MIN+i;return [m,a[m],a[m]/max*100,ref?.peaks.find(p=>p[0]===m)?.[1]??'']})]);}else{const c=msTrace(d),eic=ms.ions.map(ion=>msEIC(d,ion));gcDownload('SIMLAB-MS-ion-chromatograms.csv',[['SIMULATED MS; raw traces independent of display normalization'],['time_min','TIC_au',...ms.ions.map(m=>'EIC_mz_'+m+'_au')],...Array.from(c.times,(t,i)=>[t,c.tic[i],...eic.map(a=>a[i])])]);}}
document.addEventListener('input',e=>{if(typeof page==='undefined'||page!=='massspec')return;const t=e.target;if(t.dataset.msNumber){ms[t.dataset.msNumber]=Number(t.value);msInvalidate()}if(t.id==='msNotes'){const d=msData();if(d){d.notes=t.value;msSave()}}});
document.addEventListener('change',e=>{if(typeof page==='undefined'||page!=='massspec'||!e.target.dataset.msField)return;const t=e.target,k=t.dataset.msField;ms[k]=k==='massRange'?t.value:t.type==='checkbox'?t.checked:Number(t.value);if(k==='scan'){const d=msData();ms.peak=msTrace(d).peaks.find(p=>ms.scan*d.dt>=p.left&&ms.scan*d.dt<=p.right)?.number||null;}if(!['normalize','massRange'].includes(k))msInvalidate();msRender()});
document.addEventListener('click',e=>{const exportGC=e.target.closest('[data-ms-action="transfer"]');if(exportGC){msTransferGC();return}if(typeof page==='undefined'||page!=='massspec')return;if(msData()?.live)return;const t=e.target;try{const file=t.closest('[data-ms-dataset]'),peak=t.closest('[data-ms-peak]'),hit=t.closest('[data-ms-hit]'),ion=t.closest('[data-ms-ion]'),chart=t.closest('[data-ms-chrom]');if(file)msSelectDataset(file.dataset.msDataset);else if(peak)msSelectPeak(Number(peak.dataset.msPeak));else if(hit)ms.candidate=hit.dataset.msHit;else if(ion){const mz=Number(ion.dataset.msIon);ms.ions=[...new Set([...ms.ions,mz])].slice(-6);}else if(chart){const d=msData(),r=chart.getBoundingClientRect(),fraction=Math.max(0,Math.min(1,((e.clientX-r.left)/r.width*960-65)/875));ms.scan=Math.min(Math.floor(d.acquired/d.dt),Math.round(fraction*d.acquired/d.dt));ms.peak=msTrace(d).peaks.find(p=>ms.scan*d.dt>=p.left&&ms.scan*d.dt<=p.right)?.number||null;msInvalidate();}const a=t.closest('[data-ms-action]')?.dataset.msAction;if(a==='demo'){const m={...gcDefaults(),detectorType:'ms',column:'pdms',ovenMode:'isothermal',initial:60,runtime:8},input=GC_COMPOUNDS.filter(c=>['methanol','ethanol','isopropanol','propanol'].includes(c.id)).map(c=>({...c,concentration:.4})),r=gcSimulate(m,input);r.completed=true;msAddDataset(msMakeDataset(r,r.duration,'Alcohol tutorial','Built-in tutorial simulation'));ms.message='Alcohol tutorial loaded. Select a TIC peak, inspect its ions and search the library.';}if(a==='ions')ms.ions=msParseIons(document.getElementById('msIonInput').value);if(a==='settings'){msSpectrum();msInvalidate();ms.message='Spectrum extraction settings applied.';}if(a==='search')msSearch();if(a==='assign')msAssign();if(a==='previous'||a==='next'){const d=msData();msSetScan(ms.scan+(a==='next'?1:-1));}if(a?.startsWith('export-'))msExport(a.slice(7));if(file||peak||hit||ion||chart||a)msRender();}catch(err){ms.message=err.message;msRender()}});

if(ms.active){msSelectDataset(ms.active);ms.message='Saved MS analysis restored. Select a TIC peak to inspect its spectrum. Interrupted acquisitions retain their acquired portion.';}
